import{_ as t,c as n,a2 as o,o as a}from"./chunks/framework.BO4SuroD.js";const u=JSON.parse('{"title":"Extensions in OpenCUI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/providers/extension.md","filePath":"reference/providers/extension.md","lastUpdated":1745204925000}'),i={name:"reference/providers/extension.md"};function r(s,e,c,l,d,p){return a(),n("div",null,e[0]||(e[0]=[o('<h1 id="extensions-in-opencui" tabindex="-1">Extensions in OpenCUI <a class="header-anchor" href="#extensions-in-opencui" aria-label="Permalink to &quot;Extensions in OpenCUI&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>OpenCUI is built on an open architecture, making it easy to extend functionality for chatbots. In particular, we allow the separation between interface and implementation, allowing conversational behavior to be defined on the interface while implementation can take various forms.</p><p>On OpenCUI, we abstract the interface for every built-in functionality that might have more than one implementation, such as channels and supports, and we encourage you to do the same for application-level functionalities like payment processing. We also support platform extenions so that we can provide a better developer experience, so that it is possible to use oauth to configure these runtime extensions.</p><h3 id="types-of-extensions" tabindex="-1">Types of Extensions <a class="header-anchor" href="#types-of-extensions" aria-label="Permalink to &quot;Types of Extensions&quot;">​</a></h3><p>There are two kinds of extensions:</p><ul><li><strong>External extensions</strong>: Those that the OpenCUI platform does not have access to the source code for and can only be used with privately deployed chatbots.</li><li><strong>Internal extensions</strong>: Those that the OpenCUI platform does have access to the source code for (inside OpenCUI or Framely). Chatbots using Framely extensions cannot be exported for private deployment.</li></ul><h2 id="extension-development-process" tabindex="-1">Extension Development Process <a class="header-anchor" href="#extension-development-process" aria-label="Permalink to &quot;Extension Development Process&quot;">​</a></h2><h3 id="_1-describe-interface" tabindex="-1">1. Describe Interface <a class="header-anchor" href="#_1-describe-interface" aria-label="Permalink to &quot;1. Describe Interface&quot;">​</a></h3><p>If the service interface you need doesn&#39;t exist yet, create a new one and describe its schema on the OpenCUI platform. System service interfaces are already created for you—if you want to connect to other channels, you can use them directly, like <code>io.opencui.channel.IChannel</code>.</p><p>To create a service interface:</p><ol><li>Go to one of your orgs, select <strong>Components</strong> in left side menu, click <strong>Create</strong> on the right side.</li><li>In the <strong>Create</strong> popup window: <ul><li>Enter a label for the service component</li><li>Turn on service toggle, enable service</li><li>No need to add language for interface definitions</li><li>Click <strong>Save</strong></li></ul></li><li>Head to the <strong>Service</strong> page, in the <strong>Functions</strong> section, click <strong>Add</strong> to declare function signatures</li><li>Review your changes and merge them into master</li></ol><h3 id="_2-generate-code-stub" tabindex="-1">2. Generate Code Stub <a class="header-anchor" href="#_2-generate-code-stub" aria-label="Permalink to &quot;2. Generate Code Stub&quot;">​</a></h3><p>In your service component, click <strong>Export</strong> on the second navigation bar to extract the generated Kotlin interface file.</p><h3 id="_3-develop-extension" tabindex="-1">3. Develop Extension <a class="header-anchor" href="#_3-develop-extension" aria-label="Permalink to &quot;3. Develop Extension&quot;">​</a></h3><p>The standard way to develop an extension is within the extensions repository:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/opencui/extensions.git</span></span></code></pre></div><p>OpenCUI uses Gradle as the build system, so you can create a subdirectory to host your subproject. Using the existing build system in this repo will make it easier to contribute your native provider back to the OpenCUI community.</p><p>Implement the service interface as a standard Kotlin project. Make sure your project builds successfully:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./gradlew your_project:build</span></span></code></pre></div><h3 id="_4-register-native-provider" tabindex="-1">4. Register Native Provider <a class="header-anchor" href="#_4-register-native-provider" aria-label="Permalink to &quot;4. Register Native Provider&quot;">​</a></h3><p>Regardless of whether extensions are external or internal, you need to register their native provider on the platform so OpenCUI can generate the frontend code. For detailed instructions on registering native providers and a complete example, see the <a href="./native.html">Native Provider documentation</a>.</p><h3 id="_5-wire-and-configure-in-chatbot" tabindex="-1">5. Wire and Configure in Chatbot <a class="header-anchor" href="#_5-wire-and-configure-in-chatbot" aria-label="Permalink to &quot;5. Wire and Configure in Chatbot&quot;">​</a></h3><p>After registering a native provider, you can use it in your chatbot. For detailed instructions on wiring and configuring native providers in chatbots, see the <a href="./native.html#wire-and-configure">Native Provider documentation</a>.</p>',24)]))}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
